return {["scripts/actions/abilities/pets/mandibular_bite.lua"]={["Path"]="scripts/actions/abilities/pets/mandibular_bite.lua",["SHA256"]="ac0feedd0c123c667fa34a0e858f5f918b52705914fe4407cae7eb6897a627f6",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'mandibular_bite_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/megalith_throw.lua"]={["Path"]="scripts/actions/abilities/pets/megalith_throw.lua",["SHA256"]="7e4ee719ac5063f1369ccf8cc78f42821abe0526211d452d153b534ab8134aa1",["Text"]="-----------------------------------\n-- Megalith Throw\n-- Family: Avatar (Titan)\n-- Description: Delivers a ranged attack to a target. Additional Effect: Slow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getRangedDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.375, 2.375, 2.375 }\n    params.fTPSubsequentHits = { 2.375, 2.375, 2.375 }\n    params.str_wSC           = 0.20\n    params.agi_wSC           = 0.20\n    params.skipParry         = true\n    params.skipGuard         = true\n    params.skipBlock         = true\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobRangedMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.SLOW, power = 3000, duration = 120, tier = 8 }, -- TODO: Capture Slow tier\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/mending_halation.lua"]={["Path"]="scripts/actions/abilities/pets/mending_halation.lua",["SHA256"]="f4db8d9e751475bf85f3c016d64da4d795f691d6642a4e64a3c79b4817f64263",["Text"]="-----------------------------------\n-- Mending Halation\n-- Causes your luopan to vanish and restores HP of party members within area of effect.\n-- Obtained: Geomancer Level 75\n-- Note: Heals for a fixed amount based on Luopan Level:\n-- This is a light-based cure, so it can suffer Darkness day/weather penalties.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnAbilityCheck(player, target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, master, action)\n    local hpAmount  = math.floor(7 * pet:getMainLvl())\n    local hpRestore = hpAmount\n\n    if master and master:getMerit(xi.merit.MENDING_HALATION) > 0 then\n        hpRestore = hpRestore + (hpRestore * 0.05 * master:getMerit(xi.merit.MENDING_HALATION))\n        if master:getMod(xi.mod.MENDING_HALATION) > 0 then\n            hpRestore = hpRestore + (hpRestore * 0.04 * master:getMerit(xi.merit.MENDING_HALATION))\n        end\n    end\n\n    hpRestore = utils.clamp(hpRestore, 0, target:getMaxHP())\n\n    target:wakeUp()\n\n    if target:getID() == pet:getID() then\n        hpRestore = 0\n    end\n\n    target:addHP(hpRestore)\n\n    pet:timer(200, function(mobArg)\n        mobArg:setHP(0)\n    end)\n\n    return hpRestore\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/metallic_body.lua"]={["Path"]="scripts/actions/abilities/pets/metallic_body.lua",["SHA256"]="18d400e32d2df17106100fb136a5b591fd93dd96fe2851c2a19695678f37d204",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'metallic_body_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/meteor_strike.lua"]={["Path"]="scripts/actions/abilities/pets/meteor_strike.lua",["SHA256"]="94f07a8d6020c3aac2fa911c844af16eb5f4b5502e5d7414685f0deb61a2044e",["Text"]="-----------------------------------\n-- Meteor Strike\n-- Family: Ifrit (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Merit TP bonus.\n    local merits = 0\n\n    if summoner and summoner:isPC() then\n        merits = utils.clamp(summoner:getMerit(xi.merit.METEOR_STRIKE) - 400, 0, 3000)\n    end\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 5.3570, 8.0273, 10.7031 }\n    params.fTPBonus        = merits\n    params.int_wSC         = 0.30\n    params.element         = xi.element.FIRE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.FIRE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/meteorite.lua"]={["Path"]="scripts/actions/abilities/pets/meteorite.lua",["SHA256"]="b691417886114c8fcc8dfd37d71dd478bf2f72e0a58e6f525df31ab2718a8328",["Text"]="-----------------------------------\n-- Meteorite\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    local dint = pet:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local dmg = 500 + dint * 1.5 + petskill:getTP() / 20\n\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    target:updateEnmityFromDamage(pet, dmg)\n    target:takeDamage(dmg, pet, xi.attackType.MAGICAL, xi.damageType.LIGHT)\n    return dmg\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/mewing_lullaby.lua"]={["Path"]="scripts/actions/abilities/pets/mewing_lullaby.lua",["SHA256"]="3181f43914574a0bc107bb45b8f4390f134acdc3592e142c4b8cec727123505a",["Text"]="-----------------------------------\n-- Mewing Lullaby\n-- Family: Avatar (Cait Sith)\n-- Description: AOE light based sleep and lowers mob TP to zero\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Apply TP reset on target. (Secondary effect. Cannot miss.)\n    target:setTP(0)\n\n    local messageParams =\n    {\n        messageBypass          = false,\n        messageCantGain        = xi.msg.basic.JA_NO_EFFECT,\n        messageIsImmune        = xi.msg.basic.JA_MISS,\n        messageIsTraitResisted = xi.msg.basic.JA_MISS,\n        messageIsIncompatible  = xi.msg.basic.JA_MISS,\n        messageIsResisted      = xi.msg.basic.JA_MISS,\n        messageIsNotSuccessful = xi.msg.basic.JA_MISS,\n        messageIsSuccessful    = xi.msg.basic.JA_ENFEEB_IS,\n    }\n\n    -- Effects table.\n    local effectTable =\n    {\n        -- TODO: Get a capture of retail duration. JPWiki says 30s.\n        -- TODO: See if duration scales after 300 summoning skill.\n        [1] = { effectId = xi.effect.SLEEP_I, power = 1, duration = 30, magicalElement = xi.element.LIGHT, actorStat = xi.mod.CHR, bonusMacc = xi.summon.getSummoningSkillOverCap(pet) },\n    }\n\n    return xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, messageParams)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/moonlit_charge.lua"]={["Path"]="scripts/actions/abilities/pets/moonlit_charge.lua",["SHA256"]="0873c0e75493f5486d4cf9e77c3d966f92db36027c7e26cf4177d584ef6cab7f",["Text"]="-----------------------------------\n-- Moonlit Charge\n-- Family: Avatar (Fenrir)\n-- Description: Delivers a physical Blunt attack to a target. Additional Effect: Blind\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 1.0, 1.0, 1.0 }\n    params.fTPSubsequentHits = { 1.0, 1.0, 1.0 }\n    params.vit_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.BLINDNESS, power = 25, duration = 60 },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/mountain_buster.lua"]={["Path"]="scripts/actions/abilities/pets/mountain_buster.lua",["SHA256"]="cd5e7e167104e729883d297ccea5c17bdc76d894e074f834284a25f9a7bd48fb",["Text"]="-----------------------------------\n-- Mountain Buster\n-- Family: Avatar (Titan)\n-- Description: Delivers a Blunt attack to a target. Additional Effect: Bind\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 7.25, 9.25, 11.25 } -- TODO: Capture fTP for 2000 TP. Using linear scale for now.\n    params.fTPSubsequentHits = { 7.25, 9.25, 11.25 }\n    params.vit_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobRangedMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.BIND, power = 1, duration = math.randomInt(13, 60) }, -- TODO: Get additional captures.\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/needleshot.lua"]={["Path"]="scripts/actions/abilities/pets/needleshot.lua",["SHA256"]="300293520d40031776455b1fb3d19b4d3aed65b9d366ad90fe0bd42cca3a9ca8",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'needleshot_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/nether_blast.lua"]={["Path"]="scripts/actions/abilities/pets/nether_blast.lua",["SHA256"]="07c1878dc1813b3c46add3b47def808c972ad8afdd3e42b0e047c2b8fa61312b",["Text"]="-----------------------------------\n-- Nether Blast\n-- Family: Diabolos (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage     = pet:getMainLvl() + 2\n    params.fTP            = { 5.0, 5.0, 5.0 }\n    params.element        = xi.element.DARK\n    params.attackType     = xi.attackType.BREATH\n    params.damageType     = xi.damageType.DARK\n    params.shadowBehavior = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.canMagicBurst  = true\n    params.primaryMessage = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/nightmare.lua"]={["Path"]="scripts/actions/abilities/pets/nightmare.lua",["SHA256"]="95ba6474d72b60b5fddb1a73b2952de2e5848bc00dc668318a972b1074b3dc6d",["Text"]="-----------------------------------\n-- Nightmare - Player's Avatar\n-- AoE Sleep\n-- Sleep that is not broken from DoT effects (any dmg source that doesn't break bind).\n-- This version of it is from a player's avatar. The sleep is broken by most damage sources except other DoTs\n--\n-- see mobskills/nightmare.lua for full explanation\n-- Note: Ability range was increased in Sept. 6, 2016 update:\n-- https://wiki.ffo.jp/html/35741.html\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Check nullification.\n    if\n        xi.data.statusEffect.isTargetImmune(target, xi.effect.SLEEP_I, xi.element.DARK) or\n        xi.data.statusEffect.isTargetResistant(pet, target, xi.effect.SLEEP_I) or\n        xi.data.statusEffect.isEffectNullified(target, xi.effect.SLEEP_I, 0) or\n        target:hasStatusEffect(xi.effect.SLEEP_I)\n    then\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return xi.effect.SLEEP_I\n    end\n\n    -- Check resistance.\n    local params =\n    {\n        effectId       = xi.effect.SLEEP_I,\n        magicalElement = xi.element.DARK,\n        bonusMacc      = xi.summon.getSummoningSkillOverCap(pet),\n        actorStat      = xi.mod.INT,\n    }\n\n    local resistRate = xi.combat.magicHitRate.calculateResistRate(pet, target, params)\n    if resistRate < 0.5 then\n        petskill:setMsg(xi.msg.basic.JA_MISS_2) -- resist message\n        return xi.effect.SLEEP_I\n    end\n\n    local duration = math.floor(90 * resistRate)\n\n    -- Apply sleep and bio\n    if target:addStatusEffect(xi.effect.SLEEP_I, { power = 1, duration = duration, origin = pet, subPower = 2, tier = 4 }) then\n        petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        target:delStatusEffectSilent(xi.effect.DIA)\n        target:delStatusEffectSilent(xi.effect.BIO)\n        target:addStatusEffect(xi.effect.BIO, { power = 2, duration = duration, origin = pet, tick = 3, subPower = 10, tier = 11 })\n\n    -- Miss\n    else\n        petskill:setMsg(xi.msg.basic.JA_MISS_2)\n    end\n\n    return xi.effect.SLEEP_I\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/nihility_song.lua"]={["Path"]="scripts/actions/abilities/pets/nihility_song.lua",["SHA256"]="6c5988674635408a3c30b6154f6312f175fc70e4aae081bed8ad6c84ea50b796",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'nihility_song_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/nimble_snap.lua"]={["Path"]="scripts/actions/abilities/pets/nimble_snap.lua",["SHA256"]="f0c0aae2c68e8461fbec5a4fa625c0ad2e5a5a37b672fdfe33169f36d8eecdb7",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'nimble_snap_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/noctoshield.lua"]={["Path"]="scripts/actions/abilities/pets/noctoshield.lua",["SHA256"]="b751fad4de679316463751e6cea90141ee2850ea1734284c8d38969b2f7ce2f7",["Text"]="-----------------------------------\n-- Noctoshield\n-- Family: Avatar (Diabolos)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    if target:addStatusEffect(xi.effect.PHALANX, { power = 13, duration = duration, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.PHALANX\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/noisome_powder.lua"]={["Path"]="scripts/actions/abilities/pets/noisome_powder.lua",["SHA256"]="f76b419ec31f38982c70c9bffae69c63fdbdae594a35c1afea804ff5b29f3a8f",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'noisome_powder_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/numbing_noise.lua"]={["Path"]="scripts/actions/abilities/pets/numbing_noise.lua",["SHA256"]="5872b9bf74462601fdcf03da151bb8ec756bd7eea1da8124a499c8ba469f7104",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'numbing_noise_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/numbshroom.lua"]={["Path"]="scripts/actions/abilities/pets/numbshroom.lua",["SHA256"]="3f1605efee103907a839feb8c2dcbb8eef53a7edd4e15108cdf5ab07d3714304",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'numbshroom_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    local pet = player:getPet()\n    local checkResult = xi.actions.mobskills[skillName].onMobSkillCheck(target, pet, ability)\n    if checkResult ~= 0 then\n        return xi.msg.basic.PET_CANNOT_DO_ACTION, 0 -- TODO: verify exact message in packet.\n    end\n\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/palsy_pollen.lua"]={["Path"]="scripts/actions/abilities/pets/palsy_pollen.lua",["SHA256"]="106e05820a8840db8a7221a5e969b0f237ea096e8260c6c676c5ad2e3990f8bd",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'palsy_pollen_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/perfect_defense.lua"]={["Path"]="scripts/actions/abilities/pets/perfect_defense.lua",["SHA256"]="e0eb3890a8b566402ed22cb18abdd6510e3e4cf231d38c45aaa19b029720352e",["Text"]="-----------------------------------\n-- Perfect Defense\n-- Family: Avatar (Alexander)\n-- Notes: Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, skill, master, action)\n    if master == nil then\n        return 0\n    end\n\n    -- TODO: Audit this whole skill\n\n    local power    = master:getLocalVar('perfectDefPower')\n\n    if power == 0 then\n        power = 9000 * (master:getMP() / master:getMaxMP())\n        master:setLocalVar('perfectDefPower', power)\n        master:setMP(0)\n        master:delStatusEffect(xi.effect.ASTRAL_FLOW)\n    end\n\n    local summoningSkill = master:getSkillLevel(xi.skill.SUMMONING_MAGIC)\n    if summoningSkill > 600 then\n        summoningSkill = 600\n    end\n\n    local duration = 30 + summoningSkill / 20\n    local subPower = math.floor(98 * power / 9000)\n\n    target:delStatusEffect(xi.effect.PERFECT_DEFENSE)\n    target:addStatusEffect(xi.effect.PERFECT_DEFENSE, { power = power, duration = duration, origin = pet, tick = 3, subPower = subPower })\n\n    -- Despawn Alexander after 6 seconds.\n    pet:timer(6000, function()\n        if master then\n            master:setLocalVar('perfectDefPower', 0)\n            master:despawnPet()\n        end\n    end)\n\n    if target:getID() == action:getPrimaryTargetID() then\n        skill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n    else\n        skill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n    end\n\n    return xi.effect.PERFECT_DEFENSE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/poison_nails.lua"]={["Path"]="scripts/actions/abilities/pets/poison_nails.lua",["SHA256"]="078a76e41611ea31b4a7e229ef5c48e17e91ec1c6c9d222f222a35c32f9ef868",["Text"]="-----------------------------------\n-- Poison Nails\n-- Family: Avatar (Carbuncle)\n-- Description: Delivers a Piercing attack to a target. Additional Effect: Poison\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.PIERCING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.POISON, power = 1, tick = 3, duration = 90, tier = 1 },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/power_attack.lua"]={["Path"]="scripts/actions/abilities/pets/power_attack.lua",["SHA256"]="52489f5a0aa7122b3b3583324194fdcef711760d2e1f965270509ae6de703cc4",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'power_attack_beetle_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/predator_claws.lua"]={["Path"]="scripts/actions/abilities/pets/predator_claws.lua",["SHA256"]="3e55dd5c8542cafcf3b5da0c697db5550a2eb9e84826e93a6021f602026904ae",["Text"]="-----------------------------------\n-- Predator Claws\n-- Family: Avatar (Garuda)\n-- Description: Delivers a threefold attack to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 10.0, 10.0, 10.0 }\n    params.fTPSubsequentHits = { 10.0, 10.0, 10.0 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    params.canCrit           = true\n    params.criticalChance    = { 0.10, 0.20, 0.25 } -- TODO: Capture crit rate\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/predatory_glare.lua"]={["Path"]="scripts/actions/abilities/pets/predatory_glare.lua",["SHA256"]="f9b7ba9c90dcb34e757d970717510234318cfb7b1f098180a76465c2b1c268b5",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'predatory_glare_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/punch.lua"]={["Path"]="scripts/actions/abilities/pets/punch.lua",["SHA256"]="3c6de0265344bb382e5c5cfbc3ffff49699a0311fac518d78568ecbb18a62a95",["Text"]="-----------------------------------\n-- Punch M=3.5\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/purulent_ooze.lua"]={["Path"]="scripts/actions/abilities/pets/purulent_ooze.lua",["SHA256"]="01fcd5df808c82a1a9fd37d7de85cc5c7ff074f85322bc07da67f8dea0531095",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'purulent_ooze_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/queasyshroom.lua"]={["Path"]="scripts/actions/abilities/pets/queasyshroom.lua",["SHA256"]="492eca624869435acdcbf62058336e18007bfb6a689b3bcf042cbe40f03937cb",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'queasyshroom_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    local pet = player:getPet()\n    local checkResult = xi.actions.mobskills[skillName].onMobSkillCheck(target, pet, ability)\n    if checkResult ~= 0 then\n        return xi.msg.basic.PET_CANNOT_DO_ACTION, 0 -- TODO: verify exact message in packet.\n    end\n\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/radial_arcana.lua"]={["Path"]="scripts/actions/abilities/pets/radial_arcana.lua",["SHA256"]="e5456bc7cd83b9e10b15116a3ccde5e85e59419174899acf7fa3efca27182bcf",["Text"]="-----------------------------------\n-- Ability: Radial Arcana\n-- Causes your luopan to vanish and restores MP of party members within area of effect.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnAbilityCheck(player, target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, master, action)\n    local mpAmount  = math.floor(3 * pet:getMainLvl())\n    local mpRestore = mpAmount\n\n    if master and master:getMerit(xi.merit.RADIAL_ARCANA) > 0 then\n        mpRestore = mpRestore + (mpRestore * 0.03 * master:getMerit(xi.merit.RADIAL_ARCANA))\n        if master:getMod(xi.mod.RADIAL_ARCANA) > 0 then\n            mpRestore = mpRestore + (mpRestore * 0.05 * master:getMerit(xi.merit.RADIAL_ARCANA))\n        end\n    end\n\n    mpRestore = utils.clamp(mpRestore, 0, target:getMaxMP())\n\n    if target:getID() == pet:getID() then\n        mpRestore = 0\n    end\n\n    target:addMP(mpRestore)\n\n    pet:timer(200, function(mobArg)\n        mobArg:setHP(0)\n    end)\n\n    return mpRestore\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/rage.lua"]={["Path"]="scripts/actions/abilities/pets/rage.lua",["SHA256"]="5ceb3d9165e2b201fb4f2918eda950ad371288b3d9e6e752e47e61aed1253f85",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- 50% ATTP, -50% DEFP for 4 (0 TP) to 9 (3000 TP) minutes\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'rage_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    -- TODO: Either the mobskill below is wrong or the Ready move is customized.\n    -- Should grant a stackable BERSERK effect of 50%/-50% for 4 to 9 minutes depending on TP.\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/raise_ii.lua"]={["Path"]="scripts/actions/abilities/pets/raise_ii.lua",["SHA256"]="480d17513f3c6f5dd76daf6af1a4e0f0c77699888ebc2936dedd122506bd052a",["Text"]="-----------------------------------\n-- Raise II\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    if not target:isPC() or target:isAlive() then\n        petskill:setMsg(xi.msg.basic.NO_EFFECT)\n        return 0\n    end\n\n    petskill:setMsg(xi.msg.basic.NONE)\n    target:sendRaise(2)\n    return 0\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/random_needles.lua"]={["Path"]="scripts/actions/abilities/pets/random_needles.lua",["SHA256"]="fddf963c72d3df3736621fda14250b4ab05647493459c78501b61059f69b7fbf",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'random_needles_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/razor_fang.lua"]={["Path"]="scripts/actions/abilities/pets/razor_fang.lua",["SHA256"]="252ae473bca9e74721ad4193521329ca46bcace42c8af6cc227dc5687f28cd04",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'razor_fang_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"}};
